import heapq


def kthLargestInWindows(nums, w, k):
    n = len(nums)
    top, rest = [], []          # min-heap of (value, idx, ver); max-heap of (-value, idx, ver)
    state = [0] * n             # 0 outside, 1 in top, 2 in rest
    ver = [0] * n
    cnt = 0                     # number of live elements in top

    def push_top(i):
        ver[i] += 1
        state[i] = 1
        heapq.heappush(top, (nums[i], i, ver[i]))

    def push_rest(i):
        ver[i] += 1
        state[i] = 2
        heapq.heappush(rest, (-nums[i], i, ver[i]))

    def clean_top():
        while top and (state[top[0][1]] != 1 or ver[top[0][1]] != top[0][2]):
            heapq.heappop(top)

    def clean_rest():
        while rest and (state[rest[0][1]] != 2 or ver[rest[0][1]] != rest[0][2]):
            heapq.heappop(rest)

    out = []
    for i in range(n):
        if i >= w:
            j = i - w
            if state[j] == 1:
                state[j] = 0
                cnt -= 1
                clean_rest()
                if rest:
                    m = heapq.heappop(rest)[1]
                    push_top(m)
                    cnt += 1
            else:
                state[j] = 0
        if cnt < k:
            push_top(i)
            cnt += 1
        else:
            clean_top()
            if nums[i] > top[0][0]:
                m = heapq.heappop(top)[1]
                push_rest(m)
                push_top(i)
            else:
                push_rest(i)
        if i >= w - 1:
            clean_top()
            out.append(top[0][0])
    return out
